import{_ as p,a0 as n,w as u,s as l,ao as r,I as o,x as t,a1 as s,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"Linux 下如何通過兩個或多個輸出設備播放聲音 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 下如何通過兩個或多個輸出設備播放聲音 | LCTT (201808) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 下如何通過兩個或多個輸出設備播放聲音 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 下如何通過兩個或多個輸出設備播放聲音 | LCTT (201808) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201808/20180118 How to Play Sound Through Two or More Output Devices in Linux","title":"Linux 下如何通過兩個或多個輸出設備播放聲音","tag":"201808","desc":""},"relativePath":"201808/20180118 How to Play Sound Through Two or More Output Devices in Linux.md","filePath":"[post].md"}'),d={name:"201808/20180118 How to Play Sound Through Two or More Output Devices in Linux.md"};function h(m,e,f,x,g,T){const a=n("Link");return u(),l("div",null,[e[13]||(e[13]=r('<h1 id="linux-下如何通過兩個或多個輸出設備播放聲音" tabindex="-1">Linux 下如何通過兩個或多個輸出設備播放聲音 <a class="header-anchor" href="#linux-下如何通過兩個或多個輸出設備播放聲音" aria-label="Permalink to “Linux 下如何通過兩個或多個輸出設備播放聲音”">​</a></h1><p><img src="https://www.maketecheasier.com/assets/uploads/2018/01/output-audio-multiple-devices-featured.jpg" alt=""></p><p>在 Linux 上處理音頻是一件很痛苦的事情。Pulseaudio 的出現則是利弊參半。雖然有些事情 Pluseaudio 能夠做的更好，但有些事情則反而變得更復雜了。處理音頻的輸出就是這麼一件事情。</p><p>如果你想要在 Linux PC 上啓用多個音頻輸出，你只需要利用一個簡單的工具就能在一個虛擬j接口上啓用另一個聲音設備。這比看起來要簡單的多。</p><p>你可能會好奇為什麼要這麼做，一個很常見的情況是用電腦在電視上播放視頻，你可以同時使用電腦和電視上的揚聲器。</p><h3 id="安裝-paprefs" tabindex="-1">安裝 Paprefs <a class="header-anchor" href="#安裝-paprefs" aria-label="Permalink to “安裝 Paprefs”">​</a></h3><p>實現從多個來源啓用音頻播放的最簡單的方法是是一款名為 “paprefs” 的簡單圖形化工具。它是 PulseAudio Preferences 的縮寫。</p><p>該軟件包含在 Ubuntu 倉庫中，可以直接用 apt 來進行安裝。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install paprefs</span></span></code></pre></div><p>安裝後就能狗啓動這款程序了。</p><h3 id="啓動雙音頻播放" tabindex="-1">啓動雙音頻播放 <a class="header-anchor" href="#啓動雙音頻播放" aria-label="Permalink to “啓動雙音頻播放”">​</a></h3><p>雖然這款工具是圖形化的，但作為普通用户在命令列中輸入 <code>paprefs</code> 來啓動它恐怕還是要更容易一些。</p><p>打開的窗口中有一些標籤頁，這些標籤頁內有一些可以調整的設置項。我們這裏選擇最後那個標籤頁，“Simultaneous Output。”</p><p><img src="https://www.maketecheasier.com/assets/uploads/2018/01/sa-paprefs.jpg" alt="Paprefs on Ubuntu" title="Paprefs on Ubuntu"></p><p>這個標籤頁中沒有什麼內容，只是一個複選框用來啓用該設置。</p><p>下一步，打開常規的聲音首選項。這在不同的發行版中位於不同的位置。在 Ubuntu 上，它位於 GNOME 系統設置內。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2018/01/sa-enable.jpg" alt="Enable Simultaneous Audio" title="Enable Simultaneous Audio"></p><p>打開聲音首選項後，選擇 “output” 標籤頁。勾選 “Simultaneous output” 單選按鈕。現在它就成了你的默認輸出了。</p><h3 id="測試一下" tabindex="-1">測試一下 <a class="header-anchor" href="#測試一下" aria-label="Permalink to “測試一下”">​</a></h3><p>用什麼東西進行測試隨你喜歡，不過播放音樂總是可行的。如果你像前面建議的一樣，用視頻來進行測試也沒問題。</p><p>一切順利的話，你就能從所有連接的設備中聽到有聲音傳出了。</p><p>這就是所有要做的事了。此功能最適用於有多個設備（如 HDMI 端口和標準模擬輸出）時。你當然也可以試一下其他配置。你還需要注意，只有一個音量控制器，因此你需要根據實際情況調整物理輸出設備。</p><hr>',23)),o("p",null,[e[1]||(e[1]=t("via: ",-1)),s(a,{href:"https://www.maketecheasier.com/play-sound-through-multiple-devices-linux/"},{default:i(()=>[...e[0]||(e[0]=[t("https://www.maketecheasier.com/play-sound-through-multiple-devices-linux/",-1)])]),_:1})]),o("p",null,[e[5]||(e[5]=t("作者：",-1)),s(a,{href:"https://www.maketecheasier.com/author/nickcongleton/"},{default:i(()=>[...e[2]||(e[2]=[t("Nick Congleton",-1)])]),_:1}),e[6]||(e[6]=t(" 譯者：",-1)),s(a,{href:"https://github.com/lujun9972"},{default:i(()=>[...e[3]||(e[3]=[t("lujun9972",-1)])]),_:1}),e[7]||(e[7]=t(" 校對：",-1)),s(a,{href:"https://github.com/wxy"},{default:i(()=>[...e[4]||(e[4]=[t("wxy",-1)])]),_:1})]),o("p",null,[e[10]||(e[10]=t("本文由 ",-1)),s(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[8]||(e[8]=[t("LCTT",-1)])]),_:1}),e[11]||(e[11]=t(" 原創編譯，",-1)),s(a,{href:"https://linux.cn/"},{default:i(()=>[...e[9]||(e[9]=[t("Linux中國",-1)])]),_:1}),e[12]||(e[12]=t(" 榮譽推出",-1))])])}const L=p(d,[["render",h]]);export{k as __pageData,L as default};
